async def iterate_in_threadpool(
    iterable: typing.Iterable[T],
) -> typing.AsyncIterator[T]:
    iterator = iter(iterable)
    while True:
        try:
            yield await anyio.to_thread.run_sync(_next, iterator)
        except _StopIteration:
            break
